-- 041: NVBSE checked against vatican.va and corrected (#185, #187, #196).
--
-- The Nova Vulgata on vatican.va (archive/bible/nova_vulgata, © Libreria Editrice
-- Vaticana) was compared verse by verse with BibleGet's NVBSE in the private archive
-- BibleGet-I-O/NVBSE-vatican, which records every decision. The data half of this
-- migration lives there: apply its migrations/041-nvbse-from-archive.sql FIRST
-- (generated by its scripts/migration.py). This public half checks that the table
-- holds exactly that content and rebuilds NVBSE_idx.
--
-- What the archive changed:
--   * 21 verses that the 2015 import had merged into the verse before (Num 3:10,
--     Mt 17:22, Mc 9:45 and 47, Act 8:38, Rom 16:25, ...) are rows of their own
--     again: these were most of the "gaps" #185 listed for NVBSE;
--   * 314 words split by a space ("fi lias", "Do minus"), dashes rendered as "C",
--     a few typos ("edentem", "lœl"), Deut 32:27 (empty) repaired;
--   * vatican.va's spelling conventions (decided 2026-11-16): ae/oe spelled out
--     instead of the æ/œ ligatures, which the import had applied mechanically
--     ("Isræl" 2,584 times, so a keyword search for "Israel" found nothing),
--     curly quotation marks (straight only for a quotation nested in another),
--     em dashes; 309 parenthetical dashes both copies had lost restored;
--   * Daniel 3:91-100's Hebrew numbers (24-33) moved from the text into
--     verseequiv, as in BLPD.
-- Rows whose text is unchanged keep their embeddings; re-embed NVBSE afterwards
-- (about 20,500 rows; compute_embeddings.py --version NVBSE, both columns).
--
-- NVBSE_idx: chapters, verses_count (distinct verse numbers per chapter) and
-- verses_last per book, from the rows; Esther's ten chapters listed twice
-- (chapters = 20), as before. This also settles NVBSE's counts in #187.

BEGIN;

DO $mig$
DECLARE
    digest TEXT;
BEGIN
    SELECT md5(string_agg(concat_ws('|', book, chapter, verse, coalesce(verseequiv, ''), coalesce(verseorigin, ''), text),
                          E'\n' ORDER BY "verseID")) INTO digest FROM "NVBSE";
    IF digest <> '36529468c17399778ce56ee4b1266cb4' OR (SELECT count(*) FROM "NVBSE") <> 35878 THEN
        RAISE EXCEPTION 'NVBSE does not hold the NVBSE-vatican archive''s text (md5 %): apply NVBSE-vatican/migrations/041-nvbse-from-archive.sql first', digest;
    END IF;

    UPDATE "NVBSE_idx" i SET chapters = x.chapters, verses_count = x.cnt, verses_last = x.last
    FROM (
        SELECT book,
               CASE WHEN book = 19 THEN 2 * count(*) ELSE count(*) END AS chapters,
               CASE WHEN book = 19 THEN string_agg(d::text, ',' ORDER BY chapter) || ',' || string_agg(d::text, ',' ORDER BY chapter)
                    ELSE string_agg(d::text, ',' ORDER BY chapter) END AS cnt,
               CASE WHEN book = 19 THEN string_agg(m::text, ',' ORDER BY chapter) || ',' || string_agg(m::text, ',' ORDER BY chapter)
                    ELSE string_agg(m::text, ',' ORDER BY chapter) END AS last
        FROM (SELECT book, chapter, count(DISTINCT verse) AS d, max(verse) AS m FROM "NVBSE" GROUP BY book, chapter) c
        GROUP BY book
    ) x
    WHERE i.book = x.book
      AND (i.chapters, i.verses_count, i.verses_last) IS DISTINCT FROM (x.chapters, x.cnt, x.last);
END
$mig$;

COMMIT;
